content.query:
let Targets = datatable(Environment:string, Id:string) ['Azure', 'AZURE_VM_RESOURCE_ID', 'Arc', 'ARC_VM_RESOURCE_ID'] | extend Key=tolower(Id), VM=tostring(split(Id, '/')[-1]);
let Heartbeats = Heartbeat | where _ResourceId in~ ('AZURE_VM_RESOURCE_ID', 'ARC_VM_RESOURCE_ID') | summarize LastHeartbeat=max(TimeGenerated) by Key=tolower(_ResourceId);
let Performance = union isfuzzy=true Perf, (datatable(TimeGenerated:datetime, _ResourceId:string, ObjectName:string, CounterName:string, InstanceName:string, CounterValue:real) [])
| where TimeGenerated >= ago(5m) and _ResourceId in~ ('AZURE_VM_RESOURCE_ID', 'ARC_VM_RESOURCE_ID')
| summarize Cpu=avgif(CounterValue, ObjectName =~ 'Processor Information' and CounterName =~ '% Processor Time' and InstanceName =~ '_Total'), FreeMiB=avgif(CounterValue, ObjectName =~ 'Memory' and CounterName =~ 'Available Bytes') / 1048576.0 by Key=tolower(_ResourceId);
let Events = Event | where _ResourceId in~ ('AZURE_VM_RESOURCE_ID', 'ARC_VM_RESOURCE_ID') | summarize Events24h=count() by Key=tolower(_ResourceId);
Targets
| join kind=leftouter Heartbeats on Key
| join kind=leftouter Performance on Key
| join kind=leftouter Events on Key
| extend HeartbeatMinutes=tolong((now() - LastHeartbeat) / 1m)
| extend Attention=case(HeartbeatMinutes >= 10 or Cpu >= 80.0 or FreeMiB < 512.0, '要確認', isnull(LastHeartbeat) or isnan(Cpu) or isnan(FreeMiB) or isnull(Cpu) or isnull(FreeMiB), '未受信あり', '目安内')
| order by Environment desc
| project VM=strcat(Environment, ': ', VM), ['確認状況']=Attention, ['HB 経過分']=HeartbeatMinutes, ['CPU (%)']=iff(isnan(Cpu), real(null), round(Cpu, 1)), ['空き (MiB)']=iff(isnan(FreeMiB), real(null), round(FreeMiB, 0)), ['イベント']=coalesce(Events24h, tolong(0))
